-- Reviewed baseline. bin/schema.ts runs it as dunamismax_owner; host bootstrap owns schema app.
CREATE TABLE "app"."posts" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "app"."posts_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"slug" varchar(180) COLLATE "C" NOT NULL,
	"title" varchar(240) NOT NULL,
	"excerpt" varchar(600) DEFAULT '' NOT NULL,
	"body" text NOT NULL,
	"status" text DEFAULT 'draft' NOT NULL,
	"published_at" timestamp with time zone,
	"created_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
	"updated_at" timestamp with time zone DEFAULT CURRENT_TIMESTAMP NOT NULL,
	CONSTRAINT "posts_slug_key" UNIQUE("slug"),
	CONSTRAINT "posts_slug_check" CHECK ("app"."posts"."slug" ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
	CONSTRAINT "posts_body_check" CHECK (octet_length("app"."posts"."body") <= 16777215),
	CONSTRAINT "posts_status_check" CHECK ("app"."posts"."status" IN ('draft', 'published')),
	CONSTRAINT "posts_check" CHECK ("app"."posts"."status" <> 'published' OR "app"."posts"."published_at" IS NOT NULL)
);
--> statement-breakpoint
CREATE INDEX "posts_publication" ON "app"."posts" USING btree ("status","published_at" DESC NULLS FIRST,"id" DESC NULLS FIRST);--> statement-breakpoint
CREATE VIEW "app"."public_posts" WITH (security_barrier = true) AS (SELECT id, slug, title, excerpt, body, published_at FROM app.posts WHERE status = 'published' AND published_at <= CURRENT_TIMESTAMP);--> statement-breakpoint
-- Grants are not modeled by Drizzle; web reads only the publication view.
REVOKE ALL ON "app"."posts" FROM dunamismax_web;--> statement-breakpoint
REVOKE ALL ON ALL SEQUENCES IN SCHEMA "app" FROM dunamismax_web;--> statement-breakpoint
GRANT SELECT ON "app"."public_posts" TO dunamismax_web;--> statement-breakpoint
GRANT SELECT, INSERT, UPDATE ON "app"."posts" TO dunamismax_publishing;--> statement-breakpoint
GRANT USAGE ON SEQUENCE "app"."posts_id_seq" TO dunamismax_publishing;
